import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    addDialog: Boolean
  },
  data() {
    return {
      locationName: "",
      disgnationDept: "",
      loading: false
    };
  },
  watch: {
    addDialog: {
      async handler() {
        if (this.addDialog == true) {
          // await this.get_all_users();
          // this.fetch_users();
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_users() {
      this.masterUsers = [];
      this.listUsers.forEach(element => {
        masterUsers.push({
          full_user_name: element.full_user_name,
          user_id: element.user_id
        });
      });
    },
    close_dialog() {
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
      this.$emit("clicked", 0);
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        await this.create_master_designations();
      }
    },
    async create_master_designations() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_designation, {
          input: {
            user_email_id: data.user.user_email_id,
            organization_id: data.organization.organization_id,
            designation_name: this.disgnationDept
          }
        }));
        var response = JSON.parse(result.data.create_designation);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
